// GENERATED by scripts/build-cloud-sync.js from lib/ebayShipping.js. Do not edit.
// Shipping price, read from eBay. eBay is the source of truth for every eBay-listed item.
//
// Pure functions only, so the same rules run on this computer and in the cloud sync
// (scripts/build-cloud-sync.js copies this file to supabase/functions/ebay-sync/shipping.mjs).
//
// Where it comes from: Trading API GetItem, Item.ShippingDetails. GetMyeBaySelling (the live list)
// does not include it, which is why imported items had no shipping price at all.
//
// What gets saved on the product:
//   shipping_type  "flat"        a fixed price the buyer pays (shipping_cost holds it, in USD)
//                  "free"        free shipping on eBay (shipping_cost 0; the store never shows free
//                                shipping and charges its Stripe rate instead)
//                  "calculated"  eBay works the price out from the buyer's address (no fixed number)
//                  "none"        eBay gave no domestic shipping price (freight, pickup, not set)
//   shipping_cost  the USD price, or null when there is no fixed number. Never guessed.

const FLAT_TYPES = new Set(["flat", "flatdomesticcalculatedinternational"]);
const CALCULATED_TYPES = new Set(["calculated", "calculateddomesticflatinternational"]);

/** A Trading API amount ({ "#text": "4.99", "@_currencyID": "USD" }, "4.99" or 4.99) in USD, or null. */
function usdAmount(value) {
  if (value == null) return null;
  if (typeof value === "object") {
    const currency = value["@_currencyID"];
    if (currency && currency !== "USD") return null;
    return usdAmount(value["#text"]);
  }
  const n = Number(String(value).trim());
  return Number.isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : null;
}

const isTrue = (v) => v === true || String(v).toLowerCase() === "true";

/** The domestic option the buyer sees first (lowest ShippingServicePriority). */
function firstDomesticOption(details) {
  const options = [].concat(details?.ShippingServiceOptions || []).filter((o) => o && typeof o === "object");
  return options.sort((a, b) => Number(a.ShippingServicePriority || 99) - Number(b.ShippingServicePriority || 99))[0] || null;
}

/**
 * The shipping of one GetItem Item.
 * @returns {{ type: "flat"|"free"|"calculated"|"none", cost: number|null } | null} null when the
 *          item has no ShippingDetails at all (nothing is known, so nothing should be saved)
 */
function shippingFromTradingItem(item) {
  const details = item && typeof item === "object" ? item.ShippingDetails : null;
  if (!details || typeof details !== "object") return null;
  const kind = String(details.ShippingType || "").trim().toLowerCase();
  if (CALCULATED_TYPES.has(kind)) return { type: "calculated", cost: null };
  const option = firstDomesticOption(details);
  if (option && isTrue(option.FreeShipping)) return { type: "free", cost: 0 };
  const cost = option ? usdAmount(option.ShippingServiceCost) : null;
  if ((FLAT_TYPES.has(kind) || kind === "") && cost != null) return cost === 0 ? { type: "free", cost: 0 } : { type: "flat", cost };
  if (kind === "free") return { type: "free", cost: 0 };
  return { type: "none", cost: null };
}

/** True when no shipping has been read from eBay for this product yet. */
function isMissingShipping(product) {
  return !String(product?.shipping_type ?? "").trim();
}

/** The product fields to write when eBay's shipping differs from what is saved, or null. */
function shippingChanges(product, shipping) {
  if (!shipping) return null;
  const savedCost = product.shipping_cost == null ? null : Number(product.shipping_cost);
  if (product.shipping_type === shipping.type && savedCost === shipping.cost) return null;
  return { shipping_type: shipping.type, shipping_cost: shipping.cost };
}

export { shippingFromTradingItem, isMissingShipping, shippingChanges, usdAmount };